S = {'cc': 'FI', 'fam': 'Social', 'doc': '# FI 2025: employer social contributions (2200) and payroll taxes (3000)\n\nSource: Eläketurvakeskus (Finnish Centre for Pensions, statutory body), "Lakisääteiset sosiaalivakuutusmaksut Suomessa 2025" (`cmp20/baltic/fi/refs/etk_sosiaalivakuutusmaksut_2025.pdf`, text `etk_2025.txt`, kept by the 1.x model).\n* "Työeläkevakuutusmaksu kokonaisuudessaan on keskimäärin 24,85 % työntekijän palkasta. ... Työnantajan osuudeksi työeläkevakuutusmaksusta jää keskimäärin 17,38 %."\n* "Vuonna 2025 työnantajan osuus on 0,20 % tai 0,80 % riippuen työantajan koko palkkasummasta."\n* "Työnantajan sosiaaliturvamaksu (= sairausvakuutusmaksu) on 1,87 % palkasta."\n', 'lean': 'def c0 : Contribution := { name := "Työeläkevakuutusmaksu (työnantajan osuus, keskimäärin)", sched := Schedule.flat 1738, ceiling := -1 }\ndef c1 : Contribution := { name := "Työnantajan sairausvakuutusmaksu", sched := Schedule.flat 187, ceiling := -1 }\ndef c2 : Contribution := { name := "Työttömyysvakuutusmaksu (työnantaja)", sched := Schedule.flat 20, ceiling := -1 }\n\ndef contribs : List (Contribution × Oecd × String) :=\n  [(c0, .sscEmployer, "TyEL; Eläketurvakeskus 2025: työnantajan osuus keskimäärin 17,38 %"),\n   (c1, .sscEmployer, "Sairausvakuutuslaki 18 luku; Eläketurvakeskus 2025: 1,87 % palkasta"),\n   (c2, .sscEmployer, "Laki työttömyysetuuksien rahoituksesta; Eläketurvakeskus 2025: 0,20 % (pienempi palkkasumma)")]\n\n/-- On the household\'s wages: each adult, each contribution (borne by the employer). -/\ndef householdCharges (g : CanonGlobal) : List Charge :=\n  if g.entity == .company then [] else\n  (g.household.adults.zipIdx.filter (fun (a, _) => 0 < a.wages)).flatMap fun (a, i) =>\n    contribs.map fun (c, o, st) =>\n      charge o c.name a.wages id (fun x => c.amount x) (event := s!"adult {i + 1}") (level := .social)\n        (bearer := .employer) (statute := st)\n\n/-- On a company\'s payroll, spread evenly over its employees (ceilings per employee). -/\ndef companyCharges (g : CanonGlobal) : List Charge :=\n  if g.entity != .company || g.company.payroll ≤ 0 then [] else\n  let n : Int := max 1 (g.company.employees : Int)\n  let avg := g.company.payroll / n\n  contribs.map fun (c, o, st) =>\n    charge o c.name g.company.payroll id (fun _ => n * c.amount avg) (event := "payroll") (level := .social)\n      (statute := st)\n', 'families': [('2200/3000 employer contributions', ['.sscEmployer'], 'householdCharges g ++ companyCharges g')], 'notes': ['FI 2200/3000: ETK leaflet for 2025'], 'unsupported': [('g.household.adults.any (fun a => 0 < a.wages)', "TyEL employer share taken at the 2025 average (it varies by employer size, insurer and the employee's age band); accident and group life insurance (insurer tariffs) not modelled"), ('g.entity == .company && g.company.payroll > 2000000', 'unemployment insurance 0,80 % on the payroll above the threshold (the threshold is not in the leaflet) not modelled: 0,20 % on the whole payroll'), ('g.entity == .company && g.company.payroll > 0', 'company payroll spread evenly over its employees (per-employee ceilings applied to the average wage)')], 'guards': ['c0.amount 50000 == 8690', 'c0.amount 200000 == 34760', 'c1.amount 50000 == 935', 'c1.amount 200000 == 3740', 'c2.amount 50000 == 100', 'c2.amount 200000 == 400'], 'taxes': [{'oecd': '2200', 'tax': 'Työeläkevakuutusmaksu (työnantajan osuus, keskimäärin)', 'statute': 'TyEL; Eläketurvakeskus 2025: työnantajan osuus keskimäärin 17,38 %', 'dated': 'ETK leaflet for 2025', 'grade': 'B', 'kernel_parts': ['Contribution'], 'unsupported': []}, {'oecd': '2200', 'tax': 'Työnantajan sairausvakuutusmaksu', 'statute': 'Sairausvakuutuslaki 18 luku; Eläketurvakeskus 2025: 1,87 % palkasta', 'dated': 'ETK leaflet for 2025', 'grade': 'B', 'kernel_parts': ['Contribution'], 'unsupported': []}, {'oecd': '2200', 'tax': 'Työttömyysvakuutusmaksu (työnantaja)', 'statute': 'Laki työttömyysetuuksien rahoituksesta; Eläketurvakeskus 2025: 0,20 % (pienempi palkkasumma)', 'dated': 'ETK leaflet for 2025', 'grade': 'B', 'kernel_parts': ['Contribution'], 'unsupported': []}]}
